"use client";

import { useEffect } from "react";

import { startErrorReporting } from "@/lib/error-reporting/reporter";

/*
 * Mounts once at app root and starts client error reporting, in builds
 * with NEXT_PUBLIC_SENTRY_DSN (lib/error-reporting/, generated by
 * hatchkit). Renders nothing, so the exported HTML is the same with and
 * without an endpoint, and a build without one never loads the SDK.
 *
 * The SDK's global handlers catch uncaught errors and rejections, which
 * includes render errors that reach Next's default error boundary.
 */
export function ErrorReporting(): null {
  useEffect(() => {
    void startErrorReporting();
  }, []);
  return null;
}
